  "title": "V60 Brew Timer",
  "html": "<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<style>
  :root { color-scheme: dark; }
  body { margin: 0; font-family: var(--font-sans, system-ui); background: #efe6d6; color: #2a2118; }
  .wrap { display: grid; grid-template-columns: 240px 1fr; gap: 24px; padding: 24px; }
  .dial { position: relative; width: 240px; height: 240px; }
  .dial svg { width: 100%; height: 100%; transform: rotate(-90deg); }
  .clock { position: absolute; inset: 0; display: grid; place-items: center; font: 600 40px/1 ui-monospace, monospace; }
  button { font: inherit; border: 0; border-radius: 999px; padding: 8px 18px; background: #2a2118; color: #efe6d6; cursor: pointer; }
  button.ghost { background: transparent; color: #2a2118; box-shadow: inset 0 0 0 1px #2a2118; }
  li { list-style: none; padding: 6px 0; border-bottom: 1px dashed rgba(42,33,24,.25); }
  li.done { opacity: .5; text-decoration: line-through; }
  .now { font-size: 12px; letter-spacing: .12em; text-transform: uppercase; opacity: .7; }
</style>
</head>
<body>
<div class="wrap">
  <div>
    <div class="dial">
      <svg viewBox="0 0 240 240"><circle cx="120" cy="120" r="104" fill="none" stroke="rgba(42,33,24,.12)" stroke-width="14"/><circle id="arc" cx="120" cy="120" r="104" fill="none" stroke="#b8562f" stroke-width="14" stroke-linecap="round" stroke-dasharray="0 654"/></svg>
      <div class="clock" id="clock">0:00</div>
    </div>
    <p><button id="toggle">Başlat</button> <button class="ghost" id="reset">Sıfırla</button></p>
  </div>
  <div>
    <div class="now">V60 · tek fincan · 15 g kahve · 250 g su · 94 °C</div>
    <h2 id="stage">Bloom</h2>
    <p id="tip">Kahveyi eşit ıslat, gazını salması için bekle.</p>
    <ul id="stages"></ul>
  </div>
</div>
<script>
  const stages = [
    { name: "Bloom", a: 0, b: 45, target: "40 g", tip: "Kahveyi eşit ıslat, gazını salması için bekle." },
    { name: "1. döküm", a: 45, b: 90, target: "150 g", tip: "Ortadan dışa yavaş spiraller, kenara değme." },
    { name: "2. döküm", a: 90, b: 135, target: "250 g", tip: "Aynı ritim; sonunda demliği hafifçe döndür." },
    { name: "Süzülme", a: 135, b: 180, target: "—", tip: "Son damlaya kadar bekle; 3:00 civarı bitmeli." }
  ];
  let t = 0, timer = null;
  const fmt = (s) => Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
  function render() {
    const cur = stages.find((s) => t < s.b) || stages[stages.length - 1];
    document.getElementById("clock").textContent = fmt(t);
    document.getElementById("stage").textContent = cur.name + " · " + cur.target;
    document.getElementById("tip").textContent = cur.tip;
    document.getElementById("arc").setAttribute("stroke-dasharray", (t / 180) * 654 + " 654");
    document.getElementById("stages").innerHTML = stages
      .map((s) => '<li class="' + (t >= s.b ? "done" : "") + '">' + s.name + " · " + fmt(s.a) + "–" + fmt(s.b) + " · " + s.target + "</li>")
      .join("");
    document.getElementById("toggle").textContent = timer ? "Duraklat" : "Başlat";
  }
  document.getElementById("toggle").onclick = () => {
    if (timer) { clearInterval(timer); timer = null; }
    else timer = setInterval(() => { t = Math.min(180, t + 1); if (t >= 180) { clearInterval(timer); timer = null; } render(); }, 1000);
    render();
  };
  document.getElementById("reset").onclick = () => { if (timer) clearInterval(timer); timer = null; t = 0; render(); };
  render();
  const ro = new ResizeObserver(() => parent.postMessage({ jsonrpc: "2.0", method: "ui/notifications/size-changed", params: { height: document.documentElement.scrollHeight } }, "*"));
  ro.observe(document.body);
</script>
</body>
</html>
